export default {

	props: {
		name: {
			type: String,
			required: false,
			default: ''
		},

		placeholder: {
			type: String,
			required: false,
			default: null
		},

		value: {
			required: true
		},

		disabled: {
			type: Boolean,
			required: false,
			default: false
		},

		required: {
			type: Boolean,
			required: false,
			default: false
		}

	},

	computed: {
		getPlaceholder() {
			return this.placeholder !== null ? this.placeholder : this.name;
		}
	},

};
